# === Защита от перерасхода токенов: счётчик вызовов AI по провайдерам ===
import datetime as _dt

_ai_stats: dict = {"date": None, "groq": 0, "gemini": 0, "claude": 0, "failed": 0}
_ai_stats_lock = threading.Lock()
CLAUDE_DAILY_LIMIT = 100  # максимум платных вызовов Claude в сутки (поднято пока Gemini не работает)

def _ai_stat_bump(provider: str) -> dict:
    """Считаем вызовы по провайдеру. Сбрасываем счётчик в новые сутки (UTC)."""
    with _ai_stats_lock:
        today = _dt.date.today().isoformat()
        if _ai_stats["date"] != today:
            _ai_stats.update({"date": today, "groq": 0, "gemini": 0, "claude": 0, "failed": 0})
        _ai_stats[provider] = _ai_stats.get(provider, 0) + 1
        return dict(_ai_stats)

def needs_schedule_context(user_message):
    text = re.sub(r"\s+", " ", (user_message or "").lower()).strip()
    return any(word in text for word in (
        "когда", "старт", "начало", "начн", "поток", "распис",
        "дата", "урок", "модуль", "эфир", "практик",
    ))

def build_groq_system_prompt(user_message):
    """Короткая версия промпта для Groq: полный SYSTEM_PROMPT слишком большой и даёт 413."""
    compact_rules = """
Ты — Роза, правая рука Академии Сверхспособностей и представительница поля Натальи Дьяченко. Ты женщина — пиши от женского рода: «готова», «рада», «написала».
Твоя позиция — спокойная сила, достоинство и отбор. Не пресмыкайся, не оправдывайся, не удерживай неподходящих людей любой ценой. Ты можешь отказать и закрыть диалог.
Если спрашивают кто ты — ты Роза, помощница Академии.
Отвечай на языке клиента: русский или украинский.
Тон тёплый, живой, по-человечески. Без markdown, звёздочек и заголовков.
Отвечай кратко: 3-5 предложений, но не обрывай мысль.
Используй только данные из цен и ссылок ниже. Не придумывай курсы, тарифы, цены и обещания.
Если точной информации нет — скажи, что уточнишь у специалиста.
Если клиент хочет оплатить — уточни: оплата картой российского банка или зарубежной картой.
Если клиент пишет про доступ после оплаты — сначала попроси проверить Спам, Промоакции, Рассылки и Все письма.
Если клиент просит возврат — НЕ обещай возврат и НЕ говори «начну процесс». Сначала спроси конкретное основание: доступ не открыт, продукт не соответствует описанию, ошибка со стороны Академии или другая причина.
Если причина возврата — плохой интернет, блокировка Telegram, VPN, слабая связь или «не открывается у меня» — скажи прямо: качество связи на стороне клиента не является ошибкой Академии, возврат по этой причине не оформляется автоматически.
Если клиент обесценивает Академию, Наталью, цены или давит на жалость — коротко закрывай: «Позиция жертвы противоположна позиции мага. Обучение у Натальи — для тех, кто готов брать силу и ответственность за свой путь. Если сейчас вы выбираете позицию “я не могу, поэтому мне должны”, вы нам не подходите.» Без вопроса.
В конфликте не пиши «я готова помочь», «сделаю всё возможное», «мне очень жаль», «извините за неудобство», если вина Академии не доказана.
Не вмешивайся в воронки, отвечай только на явный вопрос или запрос.
"""
    parts = [compact_rules.strip(), PRICES.strip()]
    if needs_schedule_context(user_message):
        parts.append(SCHEDULE.strip())
    return "\n\n".join(parts)

def should_compact_groq_prompt(system_prompt):
    """Сжимаем только большой основной промпт. Короткие спец-промпты, например расшифровки, оставляем как есть."""
    prompt = system_prompt or ""
    return (
        len(prompt) > 28000
        or "=== АКТУАЛЬНЫЕ ЦЕНЫ И ССЫЛКИ НА ОПЛАТУ ===" in prompt
        or "ПРАВИЛА ПОВЕДЕНИЯ:" in prompt
    )

def _call_groq_model(model, system_prompt, user_message, max_tokens, headers, url):
    """Один вызов Groq с заданной моделью, 3 попытки при 429."""
    groq_system = system_prompt[:42000] if len(system_prompt) > 42000 else system_prompt
    body = {
        "model": model,
        "messages": [
            {"role": "system", "content": groq_system},
            {"role": "user", "content": user_message},
        ],
        "max_tokens": max_tokens,
        "temperature": 0.7,
    }
    for attempt in range(3):
        try:
            resp = requests.post(url, json=body, headers=headers, timeout=30)
            if resp.status_code == 429:
                wait = 5 * (attempt + 1)
                print(f"Groq {model} 429 (попытка {attempt+1}/3), ждём {wait}с...", flush=True)
                if attempt < 2:
                    time.sleep(wait)
                    continue
                return None
            resp.raise_for_status()
            text = resp.json()["choices"][0]["message"]["content"]
            print(f"Groq {model} ответил успешно (попытка {attempt+1})", flush=True)
            return text
        except Exception as exc:
            print(f"Groq {model} error (попытка {attempt+1}): {exc}", flush=True)
            if attempt < 2:
                time.sleep(3)
                continue
            return None
    return None


def call_groq(system_prompt, user_message, max_tokens=1024):
    """Groq API — llama-3.3-70b (12K TPM), при перегрузке — groq/compound (70K TPM)."""
    if not GROQ_API_KEY:
        return None
    url = "https://api.groq.com/openai/v1/chat/completions"
    headers = {"Authorization": f"Bearer {GROQ_API_KEY}", "Content-Type": "application/json"}
    groq_system_prompt = (
        build_groq_system_prompt(user_message)
        if should_compact_groq_prompt(system_prompt)
        else system_prompt
    )
    # Основная модель — высокое качество, но 12K токенов в минуту
    result = _call_groq_model("llama-3.3-70b-versatile", groq_system_prompt, user_message, max_tokens, headers, url)
    if result:
        _ai_stat_bump("groq")
        return result
    # Фолбек — groq/compound: 70K TPM, выдерживает одновременные запросы
    print("Groq llama перегружен — пробуем groq/compound...", flush=True)
    result = _call_groq_model("groq/compound", groq_system_prompt, user_message, max_tokens, headers, url)
    if result:
        _ai_stat_bump("groq")
        return result
    return None


def call_gemini(system_prompt, user_message, max_tokens=1024):
    """Вызов Gemini через HTTP — бесплатно.
    Пробует несколько моделей с правильными API-версиями."""
    if not GEMINI_API_KEY:
        print("Gemini: GEMINI_API_KEY не задан — пропускаем", flush=True)
        return None
    # Защита от огромных промптов (Gemini бесплатный лимит — по токенам)
    gemini_system = system_prompt[:60000] if len(system_prompt) > 60000 else system_prompt
    full_prompt = gemini_system + "\n\n---\nСообщение клиента:\n" + user_message
    body = {
        "contents": [{"parts": [{"text": full_prompt}]}],
        "generationConfig": {"maxOutputTokens": max_tokens, "temperature": 0.7},
    }
    # Пробуем все актуальные модели Gemini по очереди (рабочие первыми)
    models = [
        ("gemini-2.5-flash",               "v1beta"),
        ("gemini-2.5-flash-preview-05-20", "v1beta"),
        ("gemini-2.0-flash",               "v1beta"),
        ("gemini-2.0-flash-lite",          "v1beta"),
        ("gemini-2.0-flash-001",           "v1beta"),
    ]
    for model, api_ver in models:
        url = (
            f"https://generativelanguage.googleapis.com/{api_ver}/models/"
            f"{model}:generateContent?key={GEMINI_API_KEY}"
        )
        for attempt in range(2):
            try:
                resp = requests.post(url, json=body, timeout=30)
                if resp.status_code == 429:
                    if attempt == 0:
                        print(f"Gemini {model} 429, ждём 15с...", flush=True)
                        time.sleep(15)
                        continue
                    else:
                        print(f"Gemini {model} 429 повторно — пробуем следующую модель", flush=True)
                        break
                if resp.status_code == 404:
                    print(f"Gemini {model} 404 — модель недоступна, пробуем следующую", flush=True)
                    break
                resp.raise_for_status()
                data = resp.json()
                text = data["candidates"][0]["content"]["parts"][0]["text"]
                _ai_stat_bump("gemini")
                print(f"Gemini {model} ({api_ver}) ответил успешно", flush=True)
                return text
            except requests.exceptions.HTTPError as exc:
                print(f"Gemini {model} HTTP error: {exc}", flush=True)
                break
            except Exception as exc:
                print(f"Gemini {model} error: {exc}", flush=True)
                break
    print("Gemini: все модели не ответили", flush=True)
    return None

def call_ai(system_prompt, user_message, max_tokens=1024):
    """Groq (основной) → Gemini (запасной) → Claude (платный, с лимитом)."""
    reply = call_groq(system_prompt, user_message, max_tokens)
    if reply:
        return reply
    reply = call_gemini(system_prompt, user_message, max_tokens)
    if reply:
        return reply
    # Fallback на Claude (платный) — только если не превышен дневной лимит
    if client:
        with _ai_stats_lock:
            today = _dt.date.today().isoformat()
            if _ai_stats["date"] != today:
                _ai_stats.update({"date": today, "groq": 0, "gemini": 0, "claude": 0, "failed": 0})
            claude_today = _ai_stats.get("claude", 0)
        if claude_today >= CLAUDE_DAILY_LIMIT:
            print(f"Claude дневной лимит {CLAUDE_DAILY_LIMIT} исчерпан — AI молчит", flush=True)
            _ai_stat_bump("failed")
            telegram_notify_sync(
                f"⛔ Claude дневной лимит ({CLAUDE_DAILY_LIMIT} вызовов) исчерпан!\n"
                f"Бот не отвечает до конца дня (UTC). Проверьте Groq и Gemini."
            )
            return None
        try:
            claude_system = system_prompt[:60000] if len(system_prompt) > 60000 else system_prompt
            response = client.messages.create(
                model="claude-haiku-4-5",
                max_tokens=max_tokens,
                system=[{"type": "text", "text": claude_system, "cache_control": {"type": "ephemeral"}}],
                messages=[{"role": "user", "content": user_message}]
            )
            stats = _ai_stat_bump("claude")
            print(f"Claude fallback (платный): вызов #{stats['claude']} сегодня", flush=True)
            # Предупреждаем при первом вызове Claude и каждые 5 после
            if stats["claude"] == 1 or stats["claude"] % 5 == 0:
                telegram_notify_sync(
                    f"⚠️ Claude (платный) задействован: {stats['claude']} раз сегодня\n"
                    f"(лимит: {CLAUDE_DAILY_LIMIT}/день)\n"
                    f"Groq и Gemini не ответили — проверьте /test-ai"
                )
            return response.content[0].text
        except Exception as exc:
            print(f"Claude API error (fallback): {exc}", flush=True)
    _ai_stat_bump("failed")
    return None
conversation_history = {}

# === Фоллоу-ап: повторный вопрос через 10 минут если клиент не ответил ===
salebot_followup_timers = {}  # client_id -> threading.Timer (fallback когда нет Postgres)

def cancel_salebot_followup(client_id):
    """Отменить фоллоу-апы: и в Postgres, и in-memory таймер."""
    # In-memory fallback
    timer = salebot_followup_timers.pop(client_id, None)
    if timer:
        timer.cancel()
    # Postgres
    if DATABASE_URL:
        try:
            conn = _pg_conn()
            cur = conn.cursor()
            cur.execute(
                "UPDATE followups SET cancelled=TRUE WHERE client_id=%s AND sent=FALSE AND cancelled=FALSE",
                (str(client_id),)
            )
            rows = cur.rowcount
            conn.commit()
            cur.close()
            conn.close()
            if rows > 0:
                print(f"Persistent followups cancelled for {client_id} ({rows})", flush=True)
        except Exception as e:
            print(f"Cancel followup DB error: {e}", flush=True)

def schedule_salebot_followup(client_id, user_name, last_question):
    """Запланировать 2 фоллоу-апа: через 10 минут и через 24 часа.
    Сохраняет в Postgres — не теряется при перезапуске Railway."""
    from datetime import datetime, timedelta
    cancel_salebot_followup(client_id)

    if DATABASE_URL:
        # Персистентные фоллоу-апы в Postgres
        try:
            now = datetime.utcnow()
            conn = _pg_conn()
            cur = conn.cursor()
            cur.execute("""
                INSERT INTO followups (client_id, user_name, last_question, stage, scheduled_at)
                VALUES (%s,%s,%s,1,%s), (%s,%s,%s,2,%s)
            """, (
                str(client_id), str(user_name), str(last_question), now + timedelta(minutes=10),
                str(client_id), str(user_name), str(last_question), now + timedelta(hours=24),
            ))
            conn.commit()
            cur.close()
            conn.close()
            print(f"Persistent followups scheduled for {client_id}: 10min + 24h", flush=True)
        except Exception as e:
            print(f"Schedule followup DB error: {e}", flush=True)
    else:
        # Fallback: in-memory таймер только на 10 минут
        def send_followup():
            salebot_followup_timers.pop(client_id, None)
            rephrase_prompt = (
                "Ты — консультант академии. Клиент не ответил на вопрос. "
                "Переформулируй вопрос коротко и по-другому, тепло и без давления. "
                "Только сам вопрос, без лишних слов."
            )
            followup = call_ai(rephrase_prompt, f"Исходный вопрос: {last_question}")
            if not followup:
                followup = last_question
            try:
                send_salebot_message(client_id, followup)
                log_dialog("SaleBot", client_id, user_name, "[followup]", followup)
                telegram_notify_sync(
                    f"⏰ Фоллоу-ап (10 мин) — {user_name} ({client_id})\n"
                    f"🤖 Бот написал:\n{followup[:300]}"
                )
            except Exception as e:
                print(f"SaleBot followup send error: {e}", flush=True)

        timer = threading.Timer(600, send_followup)
        timer.daemon = True
        salebot_followup_timers[client_id] = timer
        timer.start()
        print(f"Fallback followup scheduled for {client_id} in 10 min", flush=True)

def _send_one_followup(fid, client_id, user_name, last_question, stage):
    """Отправить один фоллоу-ап и пометить sent=TRUE."""
    try:
        if stage == 1:
            prompt = (
                "Ты — консультант академии. Клиент не ответил на вопрос. "
                "Переформулируй вопрос коротко и по-другому, тепло и без давления. "
                "Только сам вопрос, без лишних слов."
            )
            text = call_ai(prompt, f"Исходный вопрос: {last_question}")
            if not text:
                text = last_question
            label = "10 мин"
        else:
            prompt = (
                "Ты — консультант академии. Клиент замолчал вчера. "
                "Напиши тёплое короткое сообщение (1-2 предложения), чтобы мягко вернуть его к разговору. "
                "Без давления. Намекни что готова помочь определиться. Не упоминай что ты бот."
            )
            text = call_ai(prompt, f"Последнее сообщение бота: {last_question}")
            if not text:
                text = "Добрый день! Хотела уточнить — вы ещё думаете насчёт курса?"
            label = "24 ч"

        resp = send_salebot_message(client_id, text)
        # Если клиент отписался / заблокировал — отменяем все его followup-ы
        if resp is not None and hasattr(resp, 'status_code') and resp.status_code in (403, 404, 410):
            print(f"Followup SKIP[unsubscribed]: client={client_id} status={resp.status_code}", flush=True)
            cancel_salebot_followup(client_id)
            return
        log_dialog("SaleBot", client_id, user_name, "[followup]", text)
        telegram_notify_sync(
            f"⏰ Фоллоу-ап ({label}) — {user_name} ({client_id})\n"
            f"🤖 Бот написал:\n{text[:300]}"
        )
        print(f"Persistent followup sent (stage={stage}) to {client_id}", flush=True)
    except Exception as e:
        err_str = str(e).lower()
        if any(w in err_str for w in ("forbidden", "unsubscribed", "blocked", "not found", "410", "403")):
            print(f"Followup SKIP[blocked]: client={client_id} err={e}", flush=True)
            cancel_salebot_followup(client_id)
        else:
            print(f"Followup send error id={fid}: {e}", flush=True)
        return

    # Пометить отправленным
    try:
        conn = _pg_conn()
        cur = conn.cursor()
        cur.execute("UPDATE followups SET sent=TRUE WHERE id=%s", (fid,))
        conn.commit()
        cur.close()
        conn.close()
    except Exception as e:
        print(f"Followup mark-sent error: {e}", flush=True)

def followup_worker():
    """Фоновый поток: каждые 60 сек проверяет Postgres на готовые фоллоу-апы."""
    import time
    while True:
        try:
            if DATABASE_URL:
                conn = _pg_conn()
                cur = conn.cursor()
                cur.execute("""
                    SELECT id, client_id, user_name, last_question, stage
                    FROM followups
                    WHERE sent=FALSE AND cancelled=FALSE AND scheduled_at <= NOW()
                    ORDER BY scheduled_at ASC
                """)
                rows = cur.fetchall()
                cur.close()
                conn.close()
                for row in rows:
                    _send_one_followup(*row)
        except Exception as e:
            print(f"Followup worker error: {e}", flush=True)
        time.sleep(60)
paused_users = set()        # Telegram-пользователи на ручном управлении
paused_salebot_clients = set()  # VK/SaleBot-клиенты на ручном управлении
forwarded_map = {}          # message_id пересланного сообщения → user_id клиента
known_users = load_known_users()
processed_salebot_events = set()
salebot_last_answer = {}
processed_getcourse_events = set()
getcourse_last_answer = {}
_boundary_closed_clients = set()  # клиенты, которым уже отправлен финальный отказ — молчим
processed_public_messages = set()
processed_public_lock = threading.Lock()
