def access_email_precheck_reply(text):
    """Первый ответ на проблему с письмом после оплаты: сначала спам, потом специалист."""
    normalized = re.sub(r"\s+", " ", (text or "").lower()).strip()
    if not normalized:
        return None
    issue_markers = (
        "письма нет", "нет письма", "письмо не пришло", "письмо не пришло",
        "не пришло письмо", "не пришёл доступ", "не пришел доступ",
        "нет доступа", "доступ не приш", "не получила доступ", "не получил доступ",
        "деньги зачислены", "оплата прошла", "оплатила", "оплатил",
        "пройшло", "не прийшов лист", "немає листа", "немає доступу",
    )
    spam_checked_markers = (
        "нет в спаме", "в спаме нет", "спам провер", "проверила спам",
        "проверил спам", "проверила все папки", "проверил все папки",
        "проверила промоакции", "проверил промоакции", "в промоакциях нет",
        "проверила все письма", "проверил все письма", "во всех письмах нет",
        "все письма провер", "в рассылках нет", "нет даже в спаме",
        "письма нет даже в спаме",
        "у спамі немає", "спам перевір", "перевірила спам", "перевірив спам",
    )
    if not any(marker in normalized for marker in issue_markers):
        return None
    if any(marker in normalized for marker in spam_checked_markers):
        return None

    email_match = re.search(r"[\w.+-]+@[\w-]+\.[\w.-]+", text or "")
    email_part = f" на {email_match.group(0)}" if email_match else ""
    return (
        f"После оплаты письмо с доступом приходит на почту{email_part} в течение 10-15 минут. "
        "Проверьте, пожалуйста, папки «Спам», «Промоакции», «Рассылки» и «Все письма», "
        "а также поиск по словам: «доступ», «Академия», «GetCourse».\n\n"
        "Если проверили все папки и письма нет — напишите, пожалуйста, email который указывали при оплате, "
        "и я передам специалисту на ручную проверку 🙏"
    )

