def limit_text(text, max_len):
    value = str(text or "")
    if len(value) <= max_len:
        return value
    return value[: max_len - 1].rstrip() + "…"

def split_telegram_text(text, limit=3900):
    """Telegram принимает до 4096 символов; режем аккуратно по абзацам."""
    value = str(text or "")
    if len(value) <= limit:
        return [value]

    chunks = []
    rest = value
    while len(rest) > limit:
        cut = rest.rfind("\n\n", 0, limit)
        if cut < limit * 0.5:
            cut = rest.rfind("\n", 0, limit)
        if cut < limit * 0.5:
            cut = rest.rfind(" ", 0, limit)
        if cut < limit * 0.5:
            cut = limit
        chunks.append(rest[:cut].strip())
        rest = rest[cut:].strip()
    if rest:
        chunks.append(rest)
    return [chunk for chunk in chunks if chunk]

def symbol_reply_looks_incomplete(reply):
    """AI иногда отдаёт расшифровку, оборванную на середине слова, или общий ответ вместо расшифровки."""
    value = re.sub(r"\s+", " ", (reply or "")).strip()
    lower = value.lower()
    if len(value) < 260:
        return True
    if not value.endswith((".", "!", "?", "…", ")", "»", "✨", "💫", "🌟")):
        return True
    generic_markers = (
        "какой-либо конкретный вопрос",
        "какой конкретный вопрос",
        "если вы хотите узнать больше",
        "я могу попытаться помочь",
        "что они значат в контексте",
        "вы уже знакомы с этими символами",
    )
    if any(marker in lower for marker in generic_markers):
        return True
    if "архетип" not in lower and "курс" not in lower and "тест" not in lower:
        return True
    return False

def fallback_reply_for_message(text):
    """Что отвечаем клиенту, если все AI-провайдеры временно не ответили.
    Возвращаем только предопределённые ответы — иначе молчим."""
    return predefined_reply_for_message(text)  # None = бот молчит, оператор видит уведомление

def build_human_attention_notice(source, user_name, client_id, user_message, bot_reply, reason, action_text):
    return (
        f"⚠️ Нужна ручная проверка: {reason}\n"
        f"Источник: {source}\n"
        f"Клиент: {user_name} ({client_id})\n\n"
        f"Сообщение клиента:\n{user_message}\n\n"
        f"Ответ бота:\n{bot_reply}\n\n"
        f"{action_text}"
    )

def find_similar(query, n=3):
    if model is None or collection is None:
        return ""
    try:
        embedding = model.encode([query]).tolist()
        results = collection.query(query_embeddings=embedding, n_results=n)
        pairs = []
        for doc, meta in zip(results["documents"][0], results["metadatas"][0]):
            pairs.append("Клиент: " + doc + " | Оператор: " + meta["answer"])
        return "\n".join(pairs)
    except Exception:
        return ""

def build_system_prompt(similar=""):
    prompt = SYSTEM_PROMPT_TEMPLATE.format(
        stream_recordings=STREAM_RECORDINGS,
        prices=PRICES,
        schedule=SCHEDULE,
        similar_section="=== ПОХОЖИЕ ДИАЛОГИ ИЗ ПРАКТИКИ ===\n" + similar
    )
    live = build_live_knowledge_section()
    if live:
        prompt += "\n\n" + live
    return prompt

