def looks_like_symbol_decode_request(text):
    normalized = re.sub(r"\s+", " ", text.lower()).strip()
    if len(normalized) > 400:
        return False

    # Исключения — это явно НЕ расшифровка символов, а вопрос по курсу/оплате
    # ВАЖНО: используем только конкретные фразы, не одиночные слова
    non_decode_markers = (
        "проплатила", "проплатил", "уже оплатил", "уже оплатила",
        "уже купил", "уже купила", "уже зарегистрировал",
        "с какого числа", "со скольки", "когда начало", "когда старт",
        "не могу войти", "нет доступа", "не открывается", "личный кабинет",
        "проходим самостоятельно", "материал самостоятельно",
        "жду ответа специалиста",
    )
    if any(m in normalized for m in non_decode_markers):
        return False

    has_color = any(word in normalized for word in COLOR_WORDS)
    has_number = (
        re.search(r"(^|[^\w])\d{1,2}([^\w]|$)", normalized) is not None
        or any(word in normalized for word in NUMBER_WORDS)
    )
    has_symbol = any(word in normalized for word in SYMBOL_WORDS)
    has_separator = "," in normalized or "\n" in text or ";" in normalized
    asks_decode = any(word in normalized for word in ("расшифр", "розшифр", "что значит", "що означає"))
    has_decode_labels = any(word in normalized for word in (
        "цвет", "колір", "цифра", "символ", "животное", "тварина"
        # убрали "число" и "числа" — слишком часто встречается в бытовом смысле
    ))
    return (
        (has_color or has_decode_labels)
        and (has_number or has_symbol or has_decode_labels)
        and (has_separator or asks_decode or has_decode_labels or len(normalized.split()) <= 12)
    )

