def is_crm_automation_tag(message):
    """Определяет системные теги SaleBot/GetCourse — не сообщения клиента, молчим."""
    if not message:
        return False
    stripped = re.sub(r"\s+", "", message.lower())  # убираем пробелы для сравнения
    # Теги автоворонки: слитные строки без пробелов из служебных слов
    tag_prefixes = (
        "автомарафон", "регмарафон", "марафонрег", "вебинаррег",
        "регкурс", "курсрег", "автокурс", "воронка",
        "автоматика", "тегклиент", "статусклиент",
        "utm_", "source=", "medium=", "campaign=",
        # латинские транслитерации автоворонки
        "avtoveb", "avtomarafon", "avtovoronka", "avtokurs",
        "regmarafon", "regkurs", "voronka",
    )
    if any(stripped.startswith(p) for p in tag_prefixes):
        return True
    # Слитная строка (без пробелов) — системный тег
    original_stripped = message.strip()
    if " " not in original_stripped:
        low = original_stripped.lower()
        # Системные события как одно слово
        system_words = ("client_unsubscribed", "user_unsubscribed", "client_subscribed",
                        "user_subscribed", "client_blocked")
        if low in system_words:
            return True
        if len(original_stripped) < 80:
            # Стандартные маркеры тегов (кириллица и латиница)
            tag_markers = ("марафон", "marathon", "курс", "course", "рейки", "руны", "reiki",
                           "рег", "авто", "avto", "voronk", "воронк", "подписк", "триггер",
                           "runy", "runes", "veb", "web", "reg_", "_reg", "avto_", "_avto")
            if any(m in low for m in tag_markers):
                return True
            # Слитные слова из тем курсов — только если строка длиннее 14 символов
            # (одиночное "ченнелинг" может быть живым ответом клиента)
            if len(original_stripped) > 14:
                topic_markers = ("ченнелинг", "ченел", "способност", "друид", "египет",
                                 "целительств", "архитектор", "проводник", "unsubscribed",
                                 "chenneling", "channeling", "druid", "egypt", "reiki")
                if any(m in low for m in topic_markers):
                    return True
    return False


def is_raw_telegram_payload(message):
    """Определяет что 'message_id' это сырой Telegram/SaleBot JSON-объект, а не текст клиента."""
    if not message:
        return False
    stripped = message.strip()
    # Выглядит как Python dict или JSON объект
    if not (stripped.startswith("{") or stripped.startswith("{'") or stripped.startswith('{"')):
        return False
    # Содержит технические поля Telegram
    tech_markers = (
        "message_id", "file_id", "file_unique_id", "mime_type",
        "file_size", "is_bot", "language_code", "first_name",
        "audio", "voice", "video", "document", "sticker",
        "photo", "animation", "video_note",
    )
    normalized = message.lower()
    matches = sum(1 for m in tech_markers if m in normalized)
    return matches >= 3  # 3+ технических поля = точно payload


def is_advertising_spam(message):
    """Определяет рекламный спам — молчим, не отвечаем."""
    if not message:
        return False
    normalized = message.lower()
    # UTM-метки в тексте = реклама чужого продукта
    if "utm_source" in normalized or "utm_campaign" in normalized or "utm_medium" in normalized:
        return True
    # Длинное сообщение (>600 символов) со ссылкой на чужой сайт
    known_domains = ("superabilityacademy.com", "ekstrasensschool", "getcourse", "t.me/mac_academy",
                     "psychic_abilities", "nataliaray.com", "superability.chatium")
    if len(message) > 600:
        has_external_link = ("http" in normalized or "vk.ru" in normalized or "vk.com" in normalized)
        is_academy_link = any(d in normalized for d in known_domains)
        if has_external_link and not is_academy_link:
            return True
    # Явные маркеры чужой рекламы
    spam_markers = (
        "минздрав", "мінздрав", "без химии", "без хімії",
        "бесплатный интенсив", "бесплатный онлайн-интенсив",
        "прямых эфира", "прямых эфиров",
        "su jok", "су джок", "сужок",
        "vk.ru/club", "vk.com/club",
        "мест всего", "участие бесплатное",
        "подписывайтесь на группу интенсива",
    )
    if any(m in normalized for m in spam_markers):
        return True
    return False


def is_video_link_only(text):
    """Сообщение — только ссылка на видео (YouTube, VK, TikTok, etc.). Молчим."""
    if not text:
        return False
    stripped = text.strip()
    video_url_markers = (
        "youtube.com/watch", "youtube.com/shorts", "youtube.com/live",
        "youtu.be/",
        "vk.com/video", "vkvideo.ru",
        "rutube.ru/video",
        "tiktok.com/", "vm.tiktok.com",
        "instagram.com/reel", "instagram.com/tv/",
        "ok.ru/video",
    )
    if not any(d in stripped.lower() for d in video_url_markers):
        return False
    # Убираем ссылки и смотрим есть ли осмысленный текст
    words = stripped.split()
    meaningful = [w for w in words if not w.startswith("http") and not w.startswith("www") and len(w) > 3]
    return len(meaningful) == 0


def is_meaningless_text(text):
    """Технический или бессмысленный текст — цифры, телефоны, одни символы, email."""
    if not text:
        return True
    stripped = text.strip()
    if not stripped:
        return True
    # Только цифры / телефонный номер
    if re.fullmatch(r'[\d\s\+\-\(\)\.]{4,}', stripped):
        return True
    # Нет ни одного буквенно-цифрового символа
    if not any(c.isalnum() for c in stripped):
        return True
    # Email-адрес сам по себе — клиент прислал почту как данные, не вопрос
    if re.fullmatch(r'[\w.+\-]+@[\w\-]+\.[\w.\-]+', stripped):
        return True
    return False


def is_passive_funnel_message(message):
    """Не отвечаем ни на что, кроме явных вопросов/запросов клиента.

    Логика: если это не явный запрос клиента — молчим. Так отсекаем
    UTM-метки, однословные теги, тексты воронок и весь прочий шум.
    """
    normalized = re.sub(r"\s+", " ", (message or "").lower()).strip()
    if not normalized:
        return True
    # Системный тег CRM/автоворонки — молчим
    if is_crm_automation_tag(message):
        return True
    # Сырой Telegram payload — молчим
    if is_raw_telegram_payload(message):
        return True
    # Рекламный спам — молчим
    if is_advertising_spam(message):
        return True
    # Видео-ссылки — молчим
    if is_video_link_only(message):
        return True
    # Бессмысленный/технический текст — молчим
    if is_meaningless_text(message):
        return True
    # Явный запрос клиента — отвечаем
    if looks_like_explicit_client_request(message):
        return False
    # Всё остальное — игнорируем
    return True

def salebot_event_id(payload):
    """Возвращает уникальный ID события. Строка 'None' (которую SaleBot шлёт
    когда реального ID нет) игнорируется — иначе все VK сообщения блокируются
    как дубликаты после первого обработанного."""
    for key in ("internal_id", "message_id", "id"):
        val = payload.get(key)
        if val is not None and val != "" and str(val).strip().lower() != "none":
            return val
    return None

def salebot_channel_info(payload):
    client_data = payload.get("client") if isinstance(payload.get("client"), dict) else {}
    client_type = salebot_value(client_data, "client_type") or salebot_value(payload, "client_type")
    group = salebot_value(client_data, "group") or salebot_value(payload, "group")
    return f"group={group or 'unknown'}, client_type={client_type or 'unknown'}"

def recursive_find(data, *keys):
    """Ищем значение в неизвестной структуре webhook payload."""
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if value is not None and value != "":
                return value
        for value in data.values():
            found = recursive_find(value, *keys)
            if found is not None and found != "":
                return found
    elif isinstance(data, list):
        for item in data:
            found = recursive_find(item, *keys)
            if found is not None and found != "":
                return found
    return None

def is_salebot_form_submission(payload):
    """Анкета/заявка GetCourse — не вопрос клиента, не отвечаем.

    ВАЖНО: проверяем только ТЕКУЩЕЕ событие (верхний уровень payload),
    НЕ сохранённые переменные клиента. У клиента может быть link_anketa /
    proxy_id в профиле от прошлых покупок — это не значит что его текущее
    сообщение "Как купить курс" является анкетой.
    """
    if not isinstance(payload, dict):
        return False

    # result=True/1 на верхнем уровне — итог отправки формы
    result_val = payload.get("result")
    if result_val in (True, 1, "True", "true", "1"):
        return True

    # event_type указывает на сделку/оплату
    event_type = str(payload.get("event_type") or "").lower()
    if any(word in event_type for word in ("deal", "order", "payment", "purchase", "lead")):
        return True

    return False

def is_salebot_comment_payload(payload, message):
    """SaleBot может присылать комментарии как webhook, но ИИ должен отвечать только в личных сообщениях."""
    normalized = message.lower()
    if any(marker in normalized for marker in (
        "fb_client_wall_reply_new_comment",
        "new_comment",
        "reply_new_comment",
        "ответить на комментарий",
    )):
        return True

    client_data = payload.get("client") if isinstance(payload.get("client"), dict) else {}
    variables = client_data.get("variables") if isinstance(client_data.get("variables"), dict) else {}
    order_variables = client_data.get("order_variables") if isinstance(client_data.get("order_variables"), dict) else {}
    comment_markers = (
        "comment_id",
        "facebook_last_comment_id",
        "facebook_media_url",
        "fb_client_wall_reply",
        "private_reply",
    )
    for source in (payload, client_data, variables, order_variables):
        if not isinstance(source, dict):
            continue
        keys_text = " ".join(str(key).lower() for key in source.keys())
        if any(marker in keys_text for marker in comment_markers):
            return True
    return False

def extract_salebot_payload(raw_payload):
    """SaleBot может прислать разные имена полей — вытаскиваем максимально гибко."""
    payload = raw_payload if isinstance(raw_payload, dict) else {}
    client_data = payload.get("client") if isinstance(payload.get("client"), dict) else {}
    message = salebot_value(payload, "message", "text", "callback_message", "msg", "body")
    # В вебхуке SaleBot верхний id часто является id сообщения, а настоящий id клиента лежит в client.id.
    client_id = (
        salebot_value(client_data, "id", "client_id")
        or salebot_value(payload, "client_id", "user_id", "platform_id")
        or salebot_value(payload, "id")
    )
    user_name = (
        salebot_value(client_data, "name", "first_name", "username")
        or salebot_value(payload, "name", "first_name", "client_name", "username")
        or f"SaleBot {client_id}"
    )
    return str(client_id) if client_id is not None else None, str(message).strip() if message else "", str(user_name)

def send_salebot_message(client_id, message):
    if not SALEBOT_API_KEY:
        raise RuntimeError("SALEBOT_API_KEY не задан в Railway Variables")

    url = f"https://chatter.salebot.pro/api/{SALEBOT_API_KEY}/message"
    body = {"client_id": client_id, "message": message}
    print(f"SaleBot send → client_id={client_id} url={url} body_len={len(message)}", flush=True)
    response = requests.post(url, json=body, timeout=20)
    print(f"SaleBot send ← status={response.status_code} response={response.text[:300]}", flush=True)
    if response.status_code >= 400:
        raise RuntimeError(f"SaleBot API error {response.status_code}: {response.text[:500]}")
    return response.text

def process_salebot_message(payload, _debug_entry=None):
    def _set_result(r):
        if _debug_entry is not None:
            _debug_entry["result"] = r

    client_id, user_message, user_name = extract_salebot_payload(payload)

    print(f"SaleBot process: client_id={client_id!r} msg={user_message[:80]!r} name={user_name!r} channel={salebot_channel_info(payload)}", flush=True)

    # Клиент написал — отменяем запланированный фоллоу-ап
    if client_id:
        cancel_salebot_followup(client_id)

    # Диалог на ручном управлении — бот молчит
    if str(client_id) in paused_salebot_clients:
        print(f"SaleBot SKIP[manual]: client={client_id} — диалог взят оператором", flush=True)
        _set_result("⏸️ ручное управление")
        return

    # Клиент уже получил финальный отказ — молчим, не повторяем
    client_key_sb = f"salebot:{client_id}"
    if client_key_sb in _boundary_closed_clients:
        print(f"SaleBot SKIP[boundary_closed]: client={client_id}", flush=True)
        _set_result("⛔ финально закрыт (уже получил отказ)")
        return

    if not client_id or not user_message:
        print(f"SaleBot SKIP[no_id_or_msg]: Payload={payload}", flush=True)
        _set_result("⛔ нет ID или текста")
        return
    event_id = salebot_event_id(payload)
    if event_id:
        event_key = str(event_id)
        if event_key in processed_salebot_events:
            print(f"SaleBot SKIP[duplicate]: event_id={event_key}", flush=True)
            _set_result("⛔ дубликат")
            return
        processed_salebot_events.add(event_key)
        if len(processed_salebot_events) > 1000:
            processed_salebot_events.clear()
    # Игнорируем сообщения с видео/аудио/файлами — только текст
    attachments = []
    msg_data = payload.get("message") if isinstance(payload.get("message"), dict) else {}
    if isinstance(msg_data, dict):
        attachments = msg_data.get("attachments", []) or []
    if not attachments:
        attachments = payload.get("attachments", []) or []
    if isinstance(attachments, list) and attachments:
        media_types = {"video", "audio", "doc", "file", "voice", "video_message", "sticker"}
        for att in attachments:
            att_type = str(att.get("type", "") if isinstance(att, dict) else att).lower()
            if any(t in att_type for t in media_types):
                print(f"SaleBot SKIP[media]: client={client_id} type={att_type}", flush=True)
                _set_result("⛔ медиафайл (видео/аудио)")
                return

    if is_salebot_outgoing(payload):
        is_input_val = salebot_value(payload, "is_input")
        direction_val = salebot_value(payload, "direction", "message_direction", "sender_type", "author_type")
        print(f"SaleBot SKIP[outgoing]: client={client_id} is_input={is_input_val!r} direction={direction_val!r}", flush=True)
        _set_result("⛔ исходящее (от бота/оператора)")
        return
    if is_salebot_form_submission(payload):
        print(f"SaleBot SKIP[form/anketa]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ форма/сделка")
        return
    if is_salebot_comment_payload(payload, user_message):
        print(f"SaleBot SKIP[comment]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ комментарий")
        return
    if is_salebot_noise_message(user_message) and not client_sent_requested_email(f"salebot:{client_id}", user_message):
        print(f"SaleBot SKIP[noise]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ шум")
        return
    # Пассивный фильтр НЕ применяем если с клиентом уже идёт диалог
    user_key_check = f"salebot:{client_id}"
    has_history = bool(conversation_history.get(user_key_check))
    if not has_history and is_passive_funnel_message(user_message):
        print(f"SaleBot SKIP[passive]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ пассивный (не вопрос)")
        return
    now = time.time()
    last_answer_at = salebot_last_answer.get(client_id, 0)
    if now - last_answer_at < 12:
        print(f"SaleBot SKIP[rate_limit]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ rate_limit (< 12 сек)")
        return
    salebot_last_answer[client_id] = now
    if user_message.startswith("message:"):
        print(f"SaleBot SKIP[system_msg]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⛔ системное сообщение")
        return

    print(f"SaleBot PASS all filters: client={client_id} msg={user_message[:80]!r}", flush=True)
    _set_result("🤖 вызван ИИ...")
    user_key = f"salebot:{client_id}"
    if looks_like_symbol_decode_request(user_message):
        reply = generate_symbol_decode_reply(user_message, language="ru")
    else:
        reply = smart_reply(user_key, user_message)
    used_fallback = False
    if not reply:
        reply = fallback_reply_for_message(user_message)
        used_fallback = True
    if not reply:
        # AI не ответил и предопределённых ответов нет — молчим, уведомляем оператора
        print(f"SaleBot SILENT[ai_silent]: client={client_id} msg={user_message[:80]!r}", flush=True)
        _set_result("⚠️ ИИ не ответил — бот молчит, ждём оператора")
        telegram_notify_sync(build_human_attention_notice(
            "SaleBot",
            user_name,
            client_id,
            user_message,
            "— (бот промолчал) —",
            "AI не ответил — бот промолчал, нужен оператор",
            f"Тейковер: /takeover_sb {client_id}\n{salebot_channel_info(payload)}",
        ))
        return
    _set_result(f"📤 отправляем ответ...")
    try:
        send_salebot_message(client_id, reply)
    except Exception as send_err:
        print(f"SaleBot SEND ERROR: client={client_id} err={send_err}", flush=True)
        _set_result(f"❌ ОШИБКА отправки: {send_err}")
        return
    log_dialog("SaleBot", client_id, user_name, user_message, reply)
    _set_result(f"✅ ответ отправлен: {reply[:80]}")

    # Финальный отказ — запоминаем, больше не отвечаем этому клиенту
    if is_final_boundary_reply(reply):
        _boundary_closed_clients.add(f"salebot:{client_id}")
        cancel_salebot_followup(client_id)
        print(f"SaleBot BOUNDARY_CLOSED: client={client_id}", flush=True)
        return

    # Если бот задал вопрос — через 10 минут напомнить если клиент не ответит
    if "?" in reply:
        schedule_salebot_followup(client_id, user_name, reply)

    reason = human_attention_reason(user_message, reply)
    if used_fallback and not reason:
        reason = "AI не ответил, клиенту отправлен резервный ответ"
    if reason:
        telegram_notify_sync(build_human_attention_notice(
            "SaleBot",
            user_name,
            client_id,
            user_message,
            reply,
            reason,
            f"Тейковер: откройте клиента в SaleBot и возьмите диалог вручную.\n{salebot_channel_info(payload)}",
        ))
    else:
        reply_preview = limit_text(reply, 2500)
        msg_id = telegram_notify_sync(
            f"👤 SaleBot — {user_name} ({client_id})\n"
            f"{salebot_channel_info(payload)}:\n{user_message}\n\n"
            f"🤖 Бот:\n{reply_preview}\n\n"
            f"↩️ Ответьте на это сообщение чтобы написать клиенту напрямую\n"
            f"▶️ Забрать диалог: /takeover_sb {client_id}\n"
            f"🔁 Вернуть боту: /release_sb {client_id}"
        )
        if msg_id:
            salebot_mirror_map[msg_id] = (str(client_id), user_name)
            if len(salebot_mirror_map) > 500:
                # чистим старые записи
                keys = list(salebot_mirror_map.keys())
                for k in keys[:200]:
                    salebot_mirror_map.pop(k, None)
    print(f"SaleBot reply sent to {client_id} ({salebot_channel_info(payload)})", flush=True)

def extract_getcourse_payload(raw_payload):
    """GetCourse может прислать webhook в JSON или form-data с разными именами полей."""
    payload = raw_payload if isinstance(raw_payload, dict) else {}
    message = recursive_find(
        payload,
        "message",
        "text",
        "body",
        "content",
        "message_text",
        "last_message",
        "answer",
    )
    client_id = recursive_find(
        payload,
        "client_id",
        "user_id",
        "profile_id",
        "account_id",
        "vk_user_id",
        "chat_id",
        "dialog_id",
        "id",
    )
    user_name = recursive_find(
        payload,
        "name",
        "first_name",
        "full_name",
        "username",
        "client_name",
    ) or f"GetCourse {client_id}"
    event_id = recursive_find(payload, "event_id", "message_id", "internal_id", "id")
    return (
        str(client_id) if client_id is not None else None,
        str(message).strip() if message else "",
        str(user_name),
        str(event_id) if event_id is not None else None,
    )

def process_getcourse_message(payload):
    # Игнорируем сообщения от ботов (например mac_academy_bot шлёт воронку)
    try:
        def _find_bot_sender(obj, depth=0):
            """Рекурсивно ищет from.is_bot=True в любом месте payload."""
            if depth > 6 or not isinstance(obj, dict):
                return None
            f = obj.get("from")
            if isinstance(f, dict) and f.get("is_bot"):
                return f.get("username", "unknown_bot")
            for v in obj.values():
                if isinstance(v, dict):
                    result = _find_bot_sender(v, depth + 1)
                    if result:
                        return result
            return None

        bot_sender = _find_bot_sender(payload)
        if bot_sender:
            print(f"GetCourse bot-message ignored (from bot: {bot_sender})", flush=True)
            return None
    except Exception:
        pass

    client_id, user_message, user_name, event_id = extract_getcourse_payload(payload)

    if not client_id or not user_message:
        print(f"GetCourse webhook ignored: no client_id/message. Payload={payload}", flush=True)
        return None
    if event_id:
        event_key = str(event_id)
        if event_key in processed_getcourse_events:
            print(f"GetCourse duplicate ignored: {event_key}", flush=True)
            return None
        processed_getcourse_events.add(event_key)
        if len(processed_getcourse_events) > 1000:
            processed_getcourse_events.clear()
    if is_salebot_noise_message(user_message) and not client_sent_requested_email(f"getcourse:{client_id}", user_message):
        print(f"GetCourse noise ignored for client {client_id}: {user_message[:120]}", flush=True)
        return None
    if is_passive_funnel_message(user_message):
        print(f"GetCourse funnel/passive ignored for client {client_id}: {user_message[:120]}", flush=True)
        return None
    now = time.time()
    last_answer_at = getcourse_last_answer.get(client_id, 0)
    if now - last_answer_at < 12:
        print(f"GetCourse rate-limit ignored for client {client_id}: {user_message[:120]}", flush=True)
        return None
    getcourse_last_answer[client_id] = now

    user_key = f"getcourse:{client_id}"
    if looks_like_symbol_decode_request(user_message):
        reply = generate_symbol_decode_reply(user_message, language="ru")
    else:
        reply = smart_reply(user_key, user_message)
    used_fallback = False
    if not reply:
        reply = fallback_reply_for_message(user_message)
        used_fallback = True
    reason = human_attention_reason(user_message, reply)
    if used_fallback and not reason:
        reason = "AI не ответил, клиенту отправлен резервный ответ"
    if reason:
        telegram_notify_sync(build_human_attention_notice(
            "GetCourse/VK",
            user_name,
            client_id,
            user_message,
            reply,
            reason,
            "Тейковер: откройте клиента в GetCourse/VK и возьмите диалог вручную.",
        ))
    else:
        telegram_notify_sync(
            f"👤 GetCourse/VK — {user_name} ({client_id}):\n{user_message}\n\n"
            f"🤖 Бот:\n{reply}"
        )
    print(f"GetCourse reply generated for {client_id}", flush=True)
    return reply

@web_app.get("/")
def healthcheck():
    return jsonify({"ok": True, "service": "mas-bot"})

_salebot_recent = []  # последние 20 входящих payload для диагностики

@web_app.route("/salebot/webhook", methods=["GET", "POST"])
@web_app.route("/salebot/webhook/", methods=["GET", "POST"])
def salebot_webhook():
    if request.method == "GET":
        print("SaleBot webhook GET check received", flush=True)
        return jsonify({"ok": True, "endpoint": "salebot/webhook", "method": "GET"})

    payload = request.get_json(silent=True)
    if payload is None:
        payload = request.form.to_dict() or request.args.to_dict()

    import datetime
    entry = {"ts": datetime.datetime.now().strftime("%H:%M:%S"), "payload": payload, "result": "⏳ обрабатывается"}
    _salebot_recent.append(entry)
    if len(_salebot_recent) > 20:
        _salebot_recent.pop(0)

    print(f"SaleBot webhook received: {payload}", flush=True)

    def run_and_track(p, e):
        try:
            process_salebot_message(p, e)
        except Exception as ex:
            e["result"] = f"❌ exception: {ex}"
            print(f"SaleBot process exception: {ex}", flush=True)

    threading.Thread(target=run_and_track, args=(payload, entry), daemon=True).start()
    return jsonify({"ok": True})

@web_app.route("/test-ai")
def test_ai_endpoint():
    """Диагностика: проверяем Gemini и SaleBot API прямо из браузера."""
    pwd = request.args.get("pwd", "")
    if pwd != os.environ.get("ADMIN_PASSWORD", "mac2024"):
        return "<h2>403</h2>", 403

    results = []
    results.append(f"<b>GROQ_API_KEY:</b> {'✅ задан (' + GROQ_API_KEY[:8] + '...)' if GROQ_API_KEY else '❌ НЕ ЗАДАН'}")
    results.append(f"<b>GEMINI_API_KEY:</b> {'✅ задан (' + GEMINI_API_KEY[:8] + '...)' if GEMINI_API_KEY else '❌ НЕ ЗАДАН'}")
    salebot_key = os.environ.get("SALEBOT_API_KEY", "")
    results.append(f"<b>SALEBOT_API_KEY:</b> {'✅ задан (' + salebot_key[:8] + '...)' if salebot_key else '❌ НЕ ЗАДАН'}")

    # Тест Groq
    if GROQ_API_KEY:
        try:
            resp = requests.post(
                "https://api.groq.com/openai/v1/chat/completions",
                headers={"Authorization": f"Bearer {GROQ_API_KEY}"},
                json={"model": "llama-3.3-70b-versatile", "messages": [{"role": "user", "content": "Скажи: работает"}], "max_tokens": 20},
                timeout=15
            )
            if resp.status_code == 200:
                text = resp.json()["choices"][0]["message"]["content"]
                results.append(f"<b>Groq [llama-3.3-70b]:</b> ✅ ответил: <i>{text[:200]}</i>")
            else:
                results.append(f"<b>Groq:</b> ❌ HTTP {resp.status_code}: {resp.text[:200]}")
        except Exception as e:
            results.append(f"<b>Groq:</b> ❌ Exception: {e}")
    else:
        results.append("<b>Groq:</b> ⏭️ ключ не задан — добавьте GROQ_API_KEY в Railway")

    # Тест Gemini — пробуем все модели по очереди
    if GEMINI_API_KEY:
        body = {
            "contents": [{"parts": [{"text": "Ответь одним словом: работает"}]}],
            "generationConfig": {"maxOutputTokens": 50, "temperature": 0.0},
        }
        for model, api_ver in [("gemini-2.5-flash-preview-05-20","v1beta"),("gemini-2.5-flash","v1beta"),("gemini-2.0-flash","v1beta"),("gemini-2.0-flash-lite","v1beta")]:
            try:
                url = (
                    f"https://generativelanguage.googleapis.com/{api_ver}/models/"
                    f"{model}:generateContent?key={GEMINI_API_KEY}"
                )
                resp = requests.post(url, json=body, timeout=15)
                if resp.status_code == 200:
                    data = resp.json()
                    text = data["candidates"][0]["content"]["parts"][0]["text"]
                    results.append(f"<b>Gemini [{model}]:</b> ✅ ответил: <i>{text[:200]}</i>")
                    break
                else:
                    results.append(f"<b>Gemini [{model}/{api_ver}]:</b> ❌ HTTP {resp.status_code}: {resp.text[:200]}")
            except Exception as e:
                results.append(f"<b>Gemini [{model}]:</b> ❌ Exception: {e}")
    else:
        results.append("<b>Gemini тест:</b> ⏭️ пропущен (ключ не задан)")

    html = "<br>".join(results)
    return f"<html><body style='font-family:sans-serif;padding:20px'><h2>AI Диагностика</h2>{html}<br><br><a href='?pwd={pwd}'>обновить</a></body></html>"


