async def telethon_public_watcher():
    if not TELEGRAM_API_ID or not TELEGRAM_API_HASH or not TELETHON_SESSION:
        print("Telethon watcher disabled: TELEGRAM_API_ID/API_HASH/TELETHON_SESSION не заданы", flush=True)
        return

    tg_client = TelegramClient(
        StringSession(TELETHON_SESSION),
        int(TELEGRAM_API_ID),
        TELEGRAM_API_HASH,
    )

    await tg_client.start()

    me = await tg_client.get_me()
    print(
        f"Telethon watcher account: id={me.id}, username={getattr(me, 'username', None)}",
        flush=True,
    )

    # ── Каналы Натальи: слушаем новые посты и подтягиваем свежие при старте ──
    # Роза читает эти каналы, чтобы знать про новые рассылки/медитации/эфиры
    KNOWLEDGE_CHANNELS = ("psychic_abilities", "channelingMAC")
    import datetime as _dt
    for channel_username in KNOWLEDGE_CHANNELS:
        try:
            channel_entity = await tg_client.get_entity(channel_username)
            # Бэкфилл: посты за последние 14 дней (переживает рестарты/redeploy)
            cutoff = _dt.datetime.now(_dt.timezone.utc) - _dt.timedelta(days=14)
            backfilled = 0
            async for msg in tg_client.iter_messages(channel_entity, limit=40):
                if msg.date and msg.date < cutoff:
                    break
                if msg.raw_text:
                    save_channel_post(channel_username, msg.id, msg.date, msg.raw_text)
                    backfilled += 1
            print(f"Telethon knowledge channel @{channel_username}: backfilled {backfilled} posts", flush=True)

            @tg_client.on(events.NewMessage(chats=channel_entity))
            async def on_channel_post(event, _ch=channel_username):
                if event.raw_text:
                    save_channel_post(_ch, event.id, event.date, event.raw_text)
                    print(f"Telethon knowledge post saved: @{_ch} id={event.id}", flush=True)
        except Exception as exc:
            print(f"Telethon knowledge channel @{channel_username} unavailable: {exc}", flush=True)

    try:
        target_chat = await tg_client.get_entity(PUBLIC_DECODE_CHAT_USERNAME)
        print(
            "Telethon watcher resolved comments chat: "
            f"id={getattr(target_chat, 'id', None)}, "
            f"title={getattr(target_chat, 'title', None)}, "
            f"username={getattr(target_chat, 'username', None)}",
            flush=True,
        )
    except Exception as exc:
        print(f"Telethon watcher cannot resolve @{PUBLIC_DECODE_CHAT_USERNAME}: {exc}", flush=True)
        return

    @tg_client.on(events.NewMessage(chats=target_chat))
    async def on_public_comment(event):
        if event.out:
            return
        sender = await event.get_sender()
        if not sender:
            return  # анонимный пост канала — нет отправителя
        if getattr(sender, "bot", False):
            return
        # user_id=777000 — GroupAnonymousBot (посты канала в группе)
        if getattr(sender, "id", None) == 777000:
            return
        # Не отвечаем на посты администраторов/Натальи
        if getattr(sender, "id", None) in ADMIN_IDS:
            return

        text = (event.raw_text or "").strip()
        if not text or text.startswith("/"):
            return
        if not mark_public_message_processed(event.chat_id, event.id):
            print(f"Telethon public duplicate ignored: chat_id={event.chat_id}, message_id={event.id}", flush=True)
            return

        print(
            f"Telethon public message seen: chat_id={event.chat_id}, message_id={event.id}, text={text[:120]}",
            flush=True,
        )

        if looks_like_symbol_decode_request(text):
            reply = await asyncio.to_thread(generate_symbol_decode_reply, text, "ru")
        elif looks_like_public_question(text):
            reply = public_question_redirect_reply()
        else:
            return

        try:
            await asyncio.to_thread(send_bot_message_sync, PUBLIC_DECODE_CHAT_ID, reply, event.id)
            print(f"Telethon public reply sent: message_id={event.id}", flush=True)
        except Exception as exc:
            print(f"Telethon public reply error: {exc}", flush=True)

    print("Telethon watcher started for public comments", flush=True)
    await tg_client.run_until_disconnected()

def run_telethon_watcher():
    try:
        asyncio.run(telethon_public_watcher())
    except Exception as exc:
        print(f"Telethon watcher crashed: {exc}", flush=True)

async def notify_admin(context, user_id, user_name, user_message, bot_reply=None, attention_reason=None):
    """Отправляет диалог в канал мониторинга."""
    if bot_reply:
        prefix = f"⚠️ Нужна ручная проверка: {attention_reason}\n\n" if attention_reason else ""
        text = (
            prefix +
            f"👤 {user_name} ({user_id}):\n{user_message}\n\n"
            f"🤖 Бот:\n{bot_reply}\n\n"
            f"Взять диалог: /takeover {user_id}"
        )
    else:
        text = (
            f"👤 {user_name} ({user_id}) [ручное управление]:\n{user_message}\n\n"
            f"Вернуть боту: /release {user_id}"
        )
    # Отправляем в канал мониторинга
    await context.bot.send_message(chat_id=LOG_CHANNEL_ID, text=text)
    # Для ручного управления — дублируем в личку чтобы можно было ответить
    if not bot_reply:
        sent = await context.bot.send_message(chat_id=ADMIN_CHAT_ID, text=text)
        forwarded_map[sent.message_id] = user_id


async def handle_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.message.from_user.id
    if user_id in ADMIN_IDS:
        return
    await update.message.reply_text(
        "Вас приветствует служба заботы Международной Академии Сверхспособностей 🌟\n\n"
        "Задайте ваш вопрос — я отвечу."
    )

async def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.message.from_user.id
    user_message = update.message.text
    user_name = update.message.from_user.first_name or str(user_id)

    # ── Сообщения от администратора ──────────────────────────────────────────
    if user_id in ADMIN_IDS:
        # /takeover USER_ID — взять диалог вручную
        if user_message.startswith("/takeover"):
            parts = user_message.split()
            if len(parts) > 1:
                tid = int(parts[1])
                paused_users.add(tid)
                await update.message.reply_text(f"✅ Взяла управление для {tid}. Бот молчит.")
            return
        # /release USER_ID — вернуть боту
        if user_message.startswith("/release"):
            parts = user_message.split()
            if len(parts) > 1:
                tid = int(parts[1])
                paused_users.discard(tid)
                await update.message.reply_text(f"✅ Бот снова отвечает пользователю {tid}.")
            return
        # /takeover_sb CLIENT_ID — взять VK-диалог вручную
        if user_message.startswith("/takeover_sb"):
            parts = user_message.split()
            if len(parts) > 1:
                cid = parts[1]
                paused_salebot_clients.add(str(cid))
                cancel_salebot_followup(cid)
                await update.message.reply_text(f"✅ Диалог {cid} забран. Бот молчит — вы отвечаете в SaleBot.")
            return
        # /release_sb CLIENT_ID — вернуть VK-диалог боту
        if user_message.startswith("/release_sb"):
            parts = user_message.split()
            if len(parts) > 1:
                cid = parts[1]
                paused_salebot_clients.discard(str(cid))
                await update.message.reply_text(f"✅ Бот снова отвечает клиенту {cid}.")
            return
        # /stats — сколько всего уникальных пользователей
        if user_message.startswith("/stats"):
            total = len(known_users)
            active = len(conversation_history)
            manual = len(paused_users)
            await update.message.reply_text(
                f"📊 Статистика бота:\n\n"
                f"👥 Всего уникальных пользователей: {total}\n"
                f"💬 Активных диалогов сейчас: {active}\n"
                f"🤝 На ручном управлении: {manual}\n\n"
                f"🤖 AI сегодня ({_ai_stats.get('date','—')}):\n"
                f"  ✅ Groq: {_ai_stats.get('groq',0)} вызовов (бесплатно)\n"
                f"  🔁 Gemini: {_ai_stats.get('gemini',0)} вызовов (бесплатно)\n"
                f"  ⚠️ Claude: {_ai_stats.get('claude',0)}/{CLAUDE_DAILY_LIMIT} вызовов (платно!)\n"
                f"  ❌ Нет ответа: {_ai_stats.get('failed',0)}"
            )
            return

        # «Запомни: ...» — добавить оперативную заметку в базу знаний Розы
        _low = user_message.lower()
        if _low.startswith(("запомни", "/note", "/запомни")):
            note = re.sub(r"^(/note|/запомни|запомни)[:,]?\s*", "", user_message, flags=re.IGNORECASE).strip()
            if not note:
                await update.message.reply_text(
                    "Напишите так:\nЗапомни: медитация Оленьей Луны — только в канале @channelingMAC"
                )
                return
            note_id = save_knowledge_note(user_name, note)
            if note_id:
                await update.message.reply_text(
                    f"📌 Запомнила (№{note_id}) — Роза сразу учитывает это в ответах.\n\n"
                    f"Все заметки: напишите «Заметки»\nУдалить: «Забудь {note_id}»"
                )
            else:
                await update.message.reply_text("❌ Не удалось сохранить заметку, посмотрите логи.")
            return
        # «Заметки» — список активных заметок
        if _low.startswith(("заметки", "/notes", "/заметки")):
            notes = list_knowledge_notes()
            if not notes:
                await update.message.reply_text("Заметок пока нет. Добавить: «Запомни: ...»")
            else:
                lines = [f"№{nid} [{str(created)[:10]}] {note}" for nid, created, note in notes]
                await update.message.reply_text("📌 Заметки Розы:\n\n" + "\n\n".join(lines)[:3900])
            return
        # «Забудь N» — удалить заметку
        if _low.startswith(("забудь", "/forget", "/забудь")):
            m = re.search(r"\d+", user_message)
            if m and deactivate_knowledge_note(int(m.group())):
                await update.message.reply_text(f"🗑 Забыла заметку №{m.group()}.")
            else:
                await update.message.reply_text("Укажите номер: «Забудь 3». Список номеров: «Заметки»")
            return

        # /list — показать кто на ручном управлении
        if user_message.startswith("/list"):
            if paused_users:
                await update.message.reply_text("На ручном управлении: " + ", ".join(str(x) for x in paused_users))
            else:
                await update.message.reply_text("Все диалоги ведёт бот.")
            return
        # Ответ на пересланное сообщение → отправить клиенту
        if update.message.reply_to_message:
            orig_id = update.message.reply_to_message.message_id
            # Ответ на Telegram-диалог
            if orig_id in forwarded_map:
                client_id = forwarded_map[orig_id]
                await context.bot.send_message(chat_id=client_id, text=user_message)
                await update.message.reply_text(f"✅ Отправлено Telegram-клиенту {client_id}.")
                return
            # Ответ на SaleBot/VK уведомление из зеркала
            if orig_id in salebot_mirror_map:
                sb_client_id, sb_name = salebot_mirror_map[orig_id]
                try:
                    send_salebot_message(sb_client_id, user_message)
                    log_dialog("SaleBot", sb_client_id, sb_name, "[оператор]", user_message)
                    await update.message.reply_text(f"✅ Отправлено в VK клиенту {sb_name} ({sb_client_id}).")
                except Exception as e:
                    await update.message.reply_text(f"❌ Ошибка отправки: {e}")
                return
        return  # прочие сообщения от админа игнорируем

    # ── Сообщения от клиентов ─────────────────────────────────────────────────
    # Фиксируем нового пользователя
    user_id_str = str(user_id)
    if user_id_str not in known_users:
        known_users.add(user_id_str)
        save_user(user_id)

    # Если диалог на ручном управлении — только пересылаем админу
    if user_id in paused_users:
        await notify_admin(context, user_id, user_name, user_message, bot_reply=None)
        return

    # Клиент уже получил финальный отказ — молчим
    tg_key = str(user_id)
    if tg_key in _boundary_closed_clients:
        print(f"TG SKIP[boundary_closed]: user={user_id}", flush=True)
        return

    # Обычный режим — отвечает бот
    # Фильтруем: видео, видео-ссылки, бессмысленный текст — молчим
    if not user_message:
        return  # видео/фото/стикер без подписи
    if is_video_link_only(user_message):
        print(f"TG SKIP[video_link]: user={user_id} msg={user_message[:80]!r}", flush=True)
        return
    has_tg_history = bool(conversation_history.get(tg_key))
    if not has_tg_history and is_meaningless_text(user_message):
        print(f"TG SKIP[meaningless]: user={user_id} msg={user_message[:80]!r}", flush=True)
        return
    # Сначала проверяем на расшифровку символов (цвет + цифра + символ)
    if looks_like_symbol_decode_request(user_message):
        reply = generate_symbol_decode_reply(user_message, language="ru")
    else:
        reply = smart_reply(user_id, user_message)
    if not reply:
        reply = fallback_reply_for_message(user_message)
    await reply_text_chunks(update.message, reply)
    log_dialog("Telegram", user_id, user_name, user_message, reply)

    # Если отправлен финальный отказ — помечаем клиента
    if reply and is_final_boundary_reply(reply):
        _boundary_closed_clients.add(tg_key)
        print(f"TG BOUNDARY_CLOSED: user={user_id}", flush=True)

    attention_reason = human_attention_reason(user_message, reply)

    # Пересылаем диалог администратору
    try:
        await notify_admin(context, user_id, user_name, user_message, bot_reply=reply, attention_reason=attention_reason)
    except Exception:
        pass  # не ломаем бота если уведомление не дошло

async def handle_public_symbol_decode(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.effective_message
    chat = update.effective_chat
    if not message or not chat or not message.text:
        return
    # Пропускаем боты
    if message.from_user and message.from_user.is_bot:
        return
    # Пропускаем посты канала (from_user=None — это автопост канала или анонимный admin)
    if not message.from_user:
        return
    # Пропускаем user_id=777000 (GroupAnonymousBot — анонимные посты канала в группе)
    if message.from_user.id == 777000:
        return
    # Не отвечаем на посты администраторов/Натальи
    if message.from_user.id in ADMIN_IDS:
        return

    print(
        "Telegram public message seen: "
        f"chat_id={chat.id}, title={chat.title}, username={getattr(chat, 'username', None)}, "
        f"text={message.text[:120]}",
        flush=True,
    )
    if not is_allowed_public_decode_chat(chat):
        print(
            "Telegram public chat ignored: "
            f"chat_id={chat.id}, title={chat.title}, username={getattr(chat, 'username', None)}",
            flush=True,
        )
        return

    user_message = message.text.strip()
    if not mark_public_message_processed(chat.id, message.message_id):
        print(f"Telegram public duplicate ignored: chat_id={chat.id}, message_id={message.message_id}", flush=True)
        return

    if looks_like_symbol_decode_request(user_message):
        reply = generate_symbol_decode_reply(user_message, language="ru")
        await reply_text_chunks(message, reply)

        try:
            await context.bot.send_message(
                chat_id=LOG_CHANNEL_ID,
                text=(
                    f"📣 Telegram комментарии — {chat.title or chat.id} ({chat.id}):\n"
                    f"{user_message}\n\n"
                    f"🤖 Расшифровка:\n{reply}"
                )[:3900],
            )
        except Exception:
            pass
        return

    if looks_like_public_question(user_message):
        await message.reply_text(public_question_redirect_reply())
        try:
            await context.bot.send_message(
                chat_id=LOG_CHANNEL_ID,
                text=(
                    f"📣 Telegram комментарии — вопрос перенаправлен в личку боту\n"
                    f"{chat.title or chat.id} ({chat.id}):\n{user_message}"
                )[:3900],
            )
        except Exception:
            pass

async def handle_chatid(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    message = update.effective_message
    if not chat or not message:
        return
    username = getattr(chat, "username", None)
    username_text = f"@{username}" if username else "нет"
    text = (
        "CHAT INFO\n"
        f"id: {chat.id}\n"
        f"type: {chat.type}\n"
        f"title: {chat.title}\n"
        f"username: {username_text}"
    )
    print(
        f"Telegram /chatid received: chat_id={chat.id}, type={chat.type}, title={chat.title}, username={username}",
        flush=True,
    )
    await message.reply_text(text)

async def handle_decode_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    message = update.effective_message
    chat = update.effective_chat
    if not message or not chat:
        return

    text = " ".join(context.args).strip()
    if not text and message.reply_to_message and message.reply_to_message.text:
        text = message.reply_to_message.text.strip()
    if not text:
        await message.reply_text("Напишите так: /decode Фиолетовый, 7, знак бесконечности, волк")
        return

    print(
        f"Telegram /decode received: chat_id={chat.id}, title={chat.title}, username={getattr(chat, 'username', None)}, text={text[:120]}",
        flush=True,
    )
    reply = generate_symbol_decode_reply(text, language="ru")
    await reply_text_chunks(message, reply)

