async def handle_mirror_reply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Обработчик ответов сотрудников в зеркальной группе.
    Если сотрудник отвечает (Reply) на уведомление бота — пересылаем текст клиенту."""
    if not update.message or not update.message.reply_to_message:
        return
    sender_id = update.effective_user.id if update.effective_user else None
    chat_id = update.effective_chat.id if update.effective_chat else None
    print(f"Mirror group reply: sender={sender_id}, chat={chat_id}, admins={ADMIN_IDS}", flush=True)
    # Только сотрудники из ADMIN_IDS
    if not (sender_id and sender_id in ADMIN_IDS):
        print(f"Mirror reply ignored: sender {sender_id} not in ADMIN_IDS", flush=True)
        return
    user_message = (update.message.text or "").strip()
    if not user_message:
        return
    orig_id = update.message.reply_to_message.message_id
    print(f"Mirror reply: orig_msg_id={orig_id}, salebot_map_keys={list(salebot_mirror_map.keys())[-5:]}, fwd_map_keys={list(forwarded_map.keys())[-5:]}", flush=True)
    # Ответ на VK/SaleBot уведомление
    if orig_id in salebot_mirror_map:
        sb_client_id, sb_name = salebot_mirror_map[orig_id]
        try:
            send_salebot_message(sb_client_id, user_message)
            log_dialog("SaleBot", sb_client_id, sb_name, "[оператор]", user_message)
            await update.message.reply_text(f"✅ Отправлено в VK клиенту {sb_name}.")
        except Exception as e:
            await update.message.reply_text(f"❌ Ошибка отправки в VK: {e}")
        return
    # Ответ на Telegram уведомление
    if orig_id in forwarded_map:
        client_id = forwarded_map[orig_id]
        try:
            await context.bot.send_message(chat_id=client_id, text=user_message)
            await update.message.reply_text(f"✅ Отправлено Telegram-клиенту.")
        except Exception as e:
            await update.message.reply_text(f"❌ Ошибка отправки: {e}")
        return

async def cmd_dialogs(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/dialogs [YYYY-MM-DD] — скачать диалоги за дату (по умолчанию вчера). Только для админов."""
    if not (update.effective_user and update.effective_user.id in ADMIN_IDS):
        return
    import datetime as _dt
    from io import BytesIO
    parts = (update.message.text or "").split()
    if len(parts) >= 2:
        try:
            day = _dt.date.fromisoformat(parts[1].strip())
        except ValueError:
            await update.message.reply_text("Неверный формат. Пример: /dialogs 2026-05-30")
            return
    else:
        day = _dt.date.today() - _dt.timedelta(days=1)

    date_from = f"{day} 00:00:00"
    date_to   = f"{day} 23:59:59"

    conn = sqlite3.connect(DIALOG_DB)
    rows = conn.execute(
        "SELECT ts, source, client_name, client_id, user_message, bot_reply "
        "FROM dialogs WHERE ts >= ? AND ts <= ? ORDER BY ts ASC",
        (date_from, date_to)
    ).fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text(f"Диалогов за {day} не найдено.")
        return

    lines = [f"=== Диалоги за {day} | записей: {len(rows)} ===\n"]
    prev_client = None
    for ts, source, name, cid, user_msg, bot_reply in rows:
        label = f"{name} ({cid}) [{source}]"
        if label != prev_client:
            lines.append(f"\n{'─'*50}")
            lines.append(f"👤 {label}")
            lines.append(f"{'─'*50}")
            prev_client = label
        lines.append(f"\n[{ts}]")
        lines.append(f"КЛИЕНТ: {user_msg}")
        lines.append(f"БОТ:    {bot_reply}")

    text = "\n".join(lines)
    buf = BytesIO(text.encode("utf-8"))
    buf.name = f"dialogs_{day}.txt"
    await update.message.reply_document(document=buf, filename=f"dialogs_{day}.txt",
                                        caption=f"📋 Диалоги за {day} ({len(rows)} записей)")

async def cmd_followup(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/followup <client_id> [текст] — отправить фоллоу-ап клиенту SaleBot прямо сейчас.
    Если текст не указан — AI сгенерирует сообщение."""
    if not (update.effective_user and update.effective_user.id in ADMIN_IDS):
        return
    parts = (update.message.text or "").split(maxsplit=2)
    if len(parts) < 2:
        await update.message.reply_text("Использование: /followup <client_id> [текст]\nПример: /followup 5105029277")
        return

    client_id = parts[1].strip()
    manual_text = parts[2].strip() if len(parts) >= 3 else ""

    if manual_text:
        message = manual_text
    else:
        await update.message.reply_text(f"⏳ Генерирую фоллоу-ап для {client_id}…")
        prompt = (
            "Ты — консультант академии. Клиент не ответил на последнее сообщение. "
            "Напиши тёплое короткое сообщение (1-2 предложения), чтобы мягко вернуть его к разговору. "
            "Без давления. Намекни что готова помочь определиться. Не упоминай что ты бот."
        )
        message = call_ai(prompt, "Напиши фоллоу-ап для клиента который замолчал.")
        if not message:
            message = "Добрый день! Хотела уточнить — вы ещё думаете? Буду рада помочь оформить 😊"

    try:
        send_salebot_message(client_id, message)
        log_dialog("SaleBot", client_id, "admin-followup", "[admin followup]", message)
        await update.message.reply_text(f"✅ Отправлено клиенту {client_id}:\n\n{message}")
    except Exception as e:
        await update.message.reply_text(f"❌ Ошибка отправки: {e}")

